input.new_string:
import { describe, expect, test } from "bun:test";
import { greet, add, greetWithMessage } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });

  test("greetWithMessage returns custom greeting", () => {
    expect(greetWithMessage("Alice", "Welcome")).toBe("Welcome, Alice!");
  });

  test("greetWithMessage works with different messages", () => {
    expect(greetWithMessage("Bob", "Good morning")).toBe("Good morning, Bob!");
  });

  test("greetWithMessage handles empty name", () => {
    expect(greetWithMessage("", "Hi")).toBe("Hi, !");
  });
});

