        "file_path": "/private/tmp/rp1-evals/c2f79bb8/workspace/src/validate-json.ts",
        "content": "/**\n * High-performance JSON validation using a single-pass character scanner.\n * Validates structural correctness without building a parsed object.\n */\n\nexport interface ValidationResult {\n  valid: boolean;\n  error?: string;\n  byteOffset?: number;\n}\n\nconst WHITESPACE = new Set([0x20, 0x09, 0x0a, 0x0d]); // space, tab, newline, carriage return\n\n/**\n * Validate JSON string using a single-pass character scanner.\n * Avoids full parse overhead by scanning character-by-character\n * and tracking structural validity without object allocation.\n */\nexport function validateJson(input: string): ValidationResult {\n  const len = input.length;\n  let pos = 0;\n\n  function error(msg: string): ValidationResult {\n    return { valid: false, error: msg, byteOffset: pos };\n  }\n\n  function skipWhitespace(): void {\n    while (pos < len && WHITESPACE.has(input.charCodeAt(pos))) {\n      pos++;\n    }\n  }\n\n  function parseValue(): ValidationResult | null {\n    skipWhitespace();\n    if (pos >= len) return error(\"Unexpected end of input\");\n\n    const ch = input.charCodeAt(pos);\n\n    if (ch === 0x22) return parseString(); // \"\n    if (ch === 0x7b) return parseObject(); // {\n    if (ch === 0x5b) return parseArray(); // [\n    if (ch === 0x74) return parseLiteral(\"true\"); // t\n    if (ch === 0x66) return parseLiteral(\"false\"); // f\n    if (ch === 0x6e) return parseLiteral(\"null\"); // n\n    if (ch === 0x2d || (ch >= 0x30 && ch <= 0x39)) return parseNumber(); // - or 0-9\n\n    return error(`Unexpected character '${input[pos]}' at position ${pos}`);\n  }\n\n  function parseString(): ValidationResult | null {\n    pos++; // skip opening \"\n    while (pos < len) {\n      const ch = input.charCodeAt(pos);\n      if (ch === 0x22) { // closing \"\n        pos++;\n        return null;\n      }\n      if (ch === 0x5c) { // backslash\n        pos++;\n        if (pos >= len) return error(\"Unexpected end of input in string escape\");\n        const esc = input.charCodeAt(pos);\n        if (\n          esc === 0x22 || esc === 0x5c || esc === 0x2f || // \" \\ /\n          esc === 0x62 || esc === 0x66 || esc === 0x6e || // b f n\n          esc === 0x72 || esc === 0x74 // r t\n        ) {\n          pos++;\n        } else if (esc === 0x75) { // u\n          pos++;\n          for (let i = 0; i < 4; i++) {\n            if (pos >= len) return error(\"Unexpected end of input in unicode escape\");\n            const hex = input.charCodeAt(pos);\n            if (\n              !((hex >= 0x30 && hex <= 0x39) || // 0-9\n                (hex >= 0x41 && hex <= 0x46) || // A-F\n                (hex >= 0x61 && hex <= 0x66))   // a-f\n            ) {\n              return error(`Invalid unicode escape character '${input[pos]}' at position ${pos}`);\n            }\n            pos++;\n          }\n        } else {\n          return error(`Invalid escape character '${input[pos]}' at position ${pos}`);\n        }\n      } else if (ch < 0x20) {\n        return error(`Invalid control character at position ${pos}`);\n      } else {\n        pos++;\n      }\n    }\n    return error(\"Unterminated string\");\n  }\n\n  function parseNumber(): ValidationResult | null {\n    if (input.charCodeAt(pos) === 0x2d) pos++; // optional -\n\n    if (pos >= len) return error(\"Unexpected end of input in number\");\n\n    if (input.charCodeAt(pos) === 0x30) { // leading 0\n      pos++;\n    } else if (input.charCodeAt(pos) >= 0x31 && input.charCodeAt(pos) <= 0x39) {\n      pos++;\n      while (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {\n        pos++;\n      }\n    } else {\n      return error(`Invalid number character '${input[pos]}' at position ${pos}`);\n    }\n\n    // fractional part\n    if (pos < len && input.charCodeAt(pos) === 0x2e) { // .\n      pos++;\n      if (pos >= len || input.charCodeAt(pos) < 0x30 || input.charCodeAt(pos) > 0x39) {\n        return error(`Expected digit after decimal point at position ${pos}`);\n      }\n      while (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {\n        pos++;\n      }\n    }\n\n    // exponent part\n    if (pos < len && (input.charCodeAt(pos) === 0x65 || input.charCodeAt(pos) === 0x45)) { // e or E\n      pos++;\n      if (pos < len && (input.charCodeAt(pos) === 0x2b || input.charCodeAt(pos) === 0x2d)) { // + or -\n        pos++;\n      }\n      if (pos >= len || input.charCodeAt(pos) < 0x30 || input.charCodeAt(pos) > 0x39) {\n        return error(`Expected digit in exponent at position ${pos}`);\n      }\n      while (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {\n        pos++;\n      }\n    }\n\n    return null;\n  }\n\n  function parseLiteral(expected: string): ValidationResult | null {\n    for (let i = 0; i < expected.length; i++) {\n      if (pos >= len || input[pos] !== expected[i]) {\n        return error(`Expected '${expected}' at position ${pos - i}`);\n      }\n      pos++;\n    }\n    return null;\n  }\n\n  function parseObject(): ValidationResult | null {\n    pos++; // skip {\n    skipWhitespace();\n\n    if (pos < len && input.charCodeAt(pos) === 0x7d) { // empty object\n      pos++;\n      return null;\n    }\n\n    while (true) {\n      skipWhitespace();\n      if (pos >= len) return error(\"Unexpected end of input in object\");\n\n      if (input.charCodeAt(pos) !== 0x22) {\n        return error(`Expected string key in object at position ${pos}`);\n      }\n\n      const keyErr = parseString();\n      if (keyErr) return keyErr;\n\n      skipWhitespace();\n      if (pos >= len || input.charCodeAt(pos) !== 0x3a) { // :\n        return error(`Expected ':' after object key at position ${pos}`);\n      }\n      pos++;\n\n      const valErr = parseValue();\n      if (valErr) return valErr;\n\n      skipWhitespace();\n      if (pos >= len) return error(\"Unexpected end of input in object\");\n\n      if (input.charCodeAt(pos) === 0x7d) { // }\n        pos++;\n        return null;\n      }\n\n      if (input.charCodeAt(pos) !== 0x2c) { // ,\n        return error(`Expected ',' or '}' in object at position ${pos}`);\n      }\n      pos++;\n    }\n  }\n\n  function parseArray(): ValidationResult | null {\n    pos++; // skip [\n    skipWhitespace();\n\n    if (pos < len && input.charCodeAt(pos) === 0x5d) { // empty array\n      pos++;\n      return null;\n    }\n\n    while (true) {\n      const valErr = parseValue();\n      if (valErr) return valErr;\n\n      skipWhitespace();\n      if (pos >= len) return error(\"Unexpected end of input in array\");\n\n      if (input.charCodeAt(pos) === 0x5d) { // ]\n        pos++;\n        return null;\n      }\n\n      if (input.charCodeAt(pos) !== 0x2c) { // ,\n        return error(`Expected ',' or ']' in array at position ${pos}`);\n      }\n      pos++;\n    }\n  }\n\n  // Main validation logic\n  skipWhitespace();\n  if (pos >= len) return error(\"Empty input\");\n\n  const result = parseValue();\n  if (result) return result;\n\n  skipWhitespace();\n  if (pos < len) {\n    return error(`Unexpected content after JSON value at position ${pos}`);\n  }\n\n  return { valid: true };\n}\n\n// CLI entry point: runs when executed directly via `bun run src/validate-json.ts`\nif (import.meta.main) {\n  const startTime = performance.now();\n  const filePath = process.argv[2];\n\n  let input: string;\n\n  if (filePath) {\n    try {\n      input = await Bun.file(filePath).text();\n    } catch (err) {\n      const message = err instanceof Error ? err.message : String(err);\n      console.error(`Error reading file: ${message}`);\n      process.exit(1);\n    }\n  } else {\n    const chunks: Uint8Array[] = [];\n    const reader = Bun.stdin.stream().getReader();\n    while (true) {\n      const { done, value } = await reader.read();\n      if (done) break;\n      chunks.push(value);\n    }\n    input = Buffer.concat(chunks).toString(\"utf-8\");\n  }\n\n  const result = validateJson(input);\n  const elapsed = (performance.now() - startTime).toFixed(2);\n\n  if (result.valid) {\n    console.log(`Valid JSON (${elapsed}ms)`);\n    process.exit(0);\n  } else {\n    console.error(`Invalid JSON: ${result.error} (byte offset: ${result.byteOffset})`);\n    console.error(`Validation took ${elapsed}ms`);\n    process.exit(1);\n  }\n}\n"
      },
