        "content": "import { describe, expect, test } from \"bun:test\";\nimport { validateJson } from \"./validate-json\";\n\ndescribe(\"validateJson\", () => {\n  describe(\"valid JSON\", () => {\n    test(\"empty object\", () => {\n      expect(validateJson(\"{}\")).toEqual({ valid: true });\n    });\n\n    test(\"empty array\", () => {\n      expect(validateJson(\"[]\")).toEqual({ valid: true });\n    });\n\n    test(\"simple object with string value\", () => {\n      expect(validateJson('{\"name\":\"Alice\"}')).toEqual({ valid: true });\n    });\n\n    test(\"nested objects\", () => {\n      expect(validateJson('{\"a\":{\"b\":{\"c\":1}}}')).toEqual({ valid: true });\n    });\n\n    test(\"array of mixed types\", () => {\n      expect(validateJson('[1,\"two\",true,null,{},[]]')).toEqual({ valid: true });\n    });\n\n    test(\"number formats\", () => {\n      expect(validateJson(\"0\")).toEqual({ valid: true });\n      expect(validateJson(\"-1\")).toEqual({ valid: true });\n      expect(validateJson(\"3.14\")).toEqual({ valid: true });\n      expect(validateJson(\"1e10\")).toEqual({ valid: true });\n      expect(validateJson(\"1E10\")).toEqual({ valid: true });\n      expect(validateJson(\"-2.5e+3\")).toEqual({ valid: true });\n      expect(validateJson(\"1.0e-5\")).toEqual({ valid: true });\n    });\n\n    test(\"string escape sequences\", () => {\n      expect(validateJson('\"hello\\\\nworld\"')).toEqual({ valid: true });\n      expect(validateJson('\"tab\\\\there\"')).toEqual({ valid: true });\n      expect(validateJson('\"back\\\\\\\\slash\"')).toEqual({ valid: true });\n      expect(validateJson('\"quote\\\\\"mark\"')).toEqual({ valid: true });\n    });\n\n    test(\"unicode escapes\", () => {\n      expect(validateJson('\"\\\\u0041\"')).toEqual({ valid: true });\n      expect(validateJson('\"\\\\u00e9\"')).toEqual({ valid: true });\n      expect(validateJson('\"\\\\uD83D\\\\uDE00\"')).toEqual({ valid: true });\n    });\n\n    test(\"whitespace around values\", () => {\n      expect(validateJson(\"  { }  \")).toEqual({ valid: true });\n      expect(validateJson(\"\\t[\\n]\\r\\n\")).toEqual({ valid: true });\n      expect(validateJson(' { \"a\" : 1 , \"b\" : 2 } ')).toEqual({ valid: true });\n    });\n\n    test(\"deeply nested structures\", () => {\n      const depth = 100;\n      const nested = \"[\".repeat(depth) + \"]\".repeat(depth);\n      expect(validateJson(nested)).toEqual({ valid: true });\n    });\n\n    test(\"large payload\", () => {\n      const entries = Array.from({ length: 1000 }, (_, i) => `\"key${i}\":${i}`);\n      const payload = `{${entries.join(\",\")}}`;\n      expect(validateJson(payload)).toEqual({ valid: true });\n    });\n\n    test(\"boolean and null literals\", () => {\n      expect(validateJson(\"true\")).toEqual({ valid: true });\n      expect(validateJson(\"false\")).toEqual({ valid: true });\n      expect(validateJson(\"null\")).toEqual({ valid: true });\n    });\n  });\n\n  describe(\"invalid JSON\", () => {\n    test(\"trailing comma in object\", () => {\n      const result = validateJson('{\"a\":1,}');\n      expect(result.valid).toBe(false);\n      expect(result.error).toBeDefined();\n    });\n\n    test(\"trailing comma in array\", () => {\n      const result = validateJson(\"[1,2,]\");\n      expect(result.valid).toBe(false);\n      expect(result.error).toBeDefined();\n    });\n\n    test(\"unquoted keys\", () => {\n      const result = validateJson(\"{a:1}\");\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Expected string key\");\n    });\n\n    test(\"single quotes\", () => {\n      const result = validateJson(\"{'a':1}\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"truncated input - incomplete object\", () => {\n      const result = validateJson('{\"a\":');\n      expect(result.valid).toBe(false);\n      expect(result.error).toBeDefined();\n    });\n\n    test(\"truncated input - incomplete array\", () => {\n      const result = validateJson(\"[1,2,\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"truncated input - incomplete string\", () => {\n      const result = validateJson('\"hello');\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Unterminated string\");\n    });\n\n    test(\"empty input\", () => {\n      const result = validateJson(\"\");\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Empty input\");\n    });\n\n    test(\"whitespace-only input\", () => {\n      const result = validateJson(\"   \");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"extra content after value\", () => {\n      const result = validateJson(\"{}[]\");\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Unexpected content after JSON value\");\n    });\n\n    test(\"invalid escape sequence\", () => {\n      const result = validateJson('\"\\\\x41\"');\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Invalid escape character\");\n    });\n\n    test(\"invalid unicode escape\", () => {\n      const result = validateJson('\"\\\\uGGGG\"');\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Invalid unicode escape\");\n    });\n\n    test(\"bare word\", () => {\n      const result = validateJson(\"undefined\");\n      expect(result.valid).toBe(false);\n    });\n\n    test(\"leading zeros in number\", () => {\n      const result = validateJson(\"01\");\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Unexpected content after JSON value\");\n    });\n\n    test(\"missing colon in object\", () => {\n      const result = validateJson('{\"a\" 1}');\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Expected ':'\");\n    });\n\n    test(\"control character in string\", () => {\n      const result = validateJson('\"hello\\x01world\"');\n      expect(result.valid).toBe(false);\n      expect(result.error).toContain(\"Invalid control character\");\n    });\n  });\n\n  describe(\"error reporting\", () => {\n    test(\"provides byte offset on error\", () => {\n      const result = validateJson('{\"valid\": tru}');\n      expect(result.valid).toBe(false);\n      expect(result.byteOffset).toBeDefined();\n      expect(typeof result.byteOffset).toBe(\"number\");\n    });\n\n    test(\"byte offset points to error location\", () => {\n      const result = validateJson(\"   !\");\n      expect(result.valid).toBe(false);\n      expect(result.byteOffset).toBe(3);\n    });\n  });\n});\n"
      },
