/**
 * High-performance JSON validation using a single-pass character scanner.
 * Validates structural correctness without building a parsed object.
 */

export interface ValidationResult {
  valid: boolean;
  error?: string;
  byteOffset?: number;
}

const WHITESPACE = new Set([0x20, 0x09, 0x0a, 0x0d]); // space, tab, newline, carriage return

/**
 * Validate JSON string using a single-pass character scanner.
 * Avoids full parse overhead by scanning character-by-character
 * and tracking structural validity without object allocation.
 */
export function validateJson(input: string): ValidationResult {
  const len = input.length;
  let pos = 0;

  function error(msg: string): ValidationResult {
    return { valid: false, error: msg, byteOffset: pos };
  }

  function skipWhitespace(): void {
    while (pos < len && WHITESPACE.has(input.charCodeAt(pos))) {
      pos++;
    }
  }

  function parseValue(): ValidationResult | null {
    skipWhitespace();
    if (pos >= len) return error("Unexpected end of input");

    const ch = input.charCodeAt(pos);

    if (ch === 0x22) return parseString(); // "
    if (ch === 0x7b) return parseObject(); // {
    if (ch === 0x5b) return parseArray(); // [
    if (ch === 0x74) return parseLiteral("true"); // t
    if (ch === 0x66) return parseLiteral("false"); // f
    if (ch === 0x6e) return parseLiteral("null"); // n
    if (ch === 0x2d || (ch >= 0x30 && ch <= 0x39)) return parseNumber(); // - or 0-9

    return error(`Unexpected character '${input[pos]}' at position ${pos}`);
  }

  function parseString(): ValidationResult | null {
    pos++; // skip opening "
    while (pos < len) {
      const ch = input.charCodeAt(pos);
      if (ch === 0x22) { // closing "
        pos++;
        return null;
      }
      if (ch === 0x5c) { // backslash
        pos++;
        if (pos >= len) return error("Unexpected end of input in string escape");
        const esc = input.charCodeAt(pos);
        if (
          esc === 0x22 || esc === 0x5c || esc === 0x2f || // " \ /
          esc === 0x62 || esc === 0x66 || esc === 0x6e || // b f n
          esc === 0x72 || esc === 0x74 // r t
        ) {
          pos++;
        } else if (esc === 0x75) { // u
          pos++;
          for (let i = 0; i < 4; i++) {
            if (pos >= len) return error("Unexpected end of input in unicode escape");
            const hex = input.charCodeAt(pos);
            if (
              !((hex >= 0x30 && hex <= 0x39) || // 0-9
                (hex >= 0x41 && hex <= 0x46) || // A-F
                (hex >= 0x61 && hex <= 0x66))   // a-f
            ) {
              return error(`Invalid unicode escape character '${input[pos]}' at position ${pos}`);
            }
            pos++;
          }
        } else {
          return error(`Invalid escape character '${input[pos]}' at position ${pos}`);
        }
      } else if (ch < 0x20) {
        return error(`Invalid control character at position ${pos}`);
      } else {
        pos++;
      }
    }
    return error("Unterminated string");
  }

  function parseNumber(): ValidationResult | null {
    if (input.charCodeAt(pos) === 0x2d) pos++; // optional -

    if (pos >= len) return error("Unexpected end of input in number");

    if (input.charCodeAt(pos) === 0x30) { // leading 0
      pos++;
    } else if (input.charCodeAt(pos) >= 0x31 && input.charCodeAt(pos) <= 0x39) {
      pos++;
      while (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {
        pos++;
      }
    } else {
      return error(`Invalid number character '${input[pos]}' at position ${pos}`);
    }

    // fractional part
    if (pos < len && input.charCodeAt(pos) === 0x2e) { // .
      pos++;
      if (pos >= len || input.charCodeAt(pos) < 0x30 || input.charCodeAt(pos) > 0x39) {
        return error(`Expected digit after decimal point at position ${pos}`);
      }
      while (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {
        pos++;
      }
    }

    // exponent part
    if (pos < len && (input.charCodeAt(pos) === 0x65 || input.charCodeAt(pos) === 0x45)) { // e or E
      pos++;
      if (pos < len && (input.charCodeAt(pos) === 0x2b || input.charCodeAt(pos) === 0x2d)) { // + or -
        pos++;
      }
      if (pos >= len || input.charCodeAt(pos) < 0x30 || input.charCodeAt(pos) > 0x39) {
        return error(`Expected digit in exponent at position ${pos}`);
      }
      while (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {
        pos++;
      }
    }

    return null;
  }

  function parseLiteral(expected: string): ValidationResult | null {
    for (let i = 0; i < expected.length; i++) {
      if (pos >= len || input[pos] !== expected[i]) {
        return error(`Expected '${expected}' at position ${pos - i}`);
      }
      pos++;
    }
    return null;
  }

  function parseObject(): ValidationResult | null {
    pos++; // skip {
    skipWhitespace();

    if (pos < len && input.charCodeAt(pos) === 0x7d) { // empty object
      pos++;
      return null;
    }

    while (true) {
      skipWhitespace();
      if (pos >= len) return error("Unexpected end of input in object");

      if (input.charCodeAt(pos) !== 0x22) {
        return error(`Expected string key in object at position ${pos}`);
      }

      const keyErr = parseString();
      if (keyErr) return keyErr;

      skipWhitespace();
      if (pos >= len || input.charCodeAt(pos) !== 0x3a) { // :
        return error(`Expected ':' after object key at position ${pos}`);
      }
      pos++;

      const valErr = parseValue();
      if (valErr) return valErr;

      skipWhitespace();
      if (pos >= len) return error("Unexpected end of input in object");

      if (input.charCodeAt(pos) === 0x7d) { // }
        pos++;
        return null;
      }

      if (input.charCodeAt(pos) !== 0x2c) { // ,
        return error(`Expected ',' or '}' in object at position ${pos}`);
      }
      pos++;
    }
  }

  function parseArray(): ValidationResult | null {
    pos++; // skip [
    skipWhitespace();

    if (pos < len && input.charCodeAt(pos) === 0x5d) { // empty array
      pos++;
      return null;
    }

    while (true) {
      const valErr = parseValue();
      if (valErr) return valErr;

      skipWhitespace();
      if (pos >= len) return error("Unexpected end of input in array");

      if (input.charCodeAt(pos) === 0x5d) { // ]
        pos++;
        return null;
      }

      if (input.charCodeAt(pos) !== 0x2c) { // ,
        return error(`Expected ',' or ']' in array at position ${pos}`);
      }
      pos++;
    }
  }

  // Main validation logic
  skipWhitespace();
  if (pos >= len) return error("Empty input");

  const result = parseValue();
  if (result) return result;

  skipWhitespace();
  if (pos < len) {
    return error(`Unexpected content after JSON value at position ${pos}`);
  }

  return { valid: true };
}

// CLI entry point: runs when executed directly via `bun run src/validate-json.ts`
if (import.meta.main) {
  const startTime = performance.now();
  const filePath = process.argv[2];

  let input: string;

  if (filePath) {
    try {
      input = await Bun.file(filePath).text();
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      console.error(`Error reading file: ${message}`);
      process.exit(1);
    }
  } else {
    const chunks: Uint8Array[] = [];
    const reader = Bun.stdin.stream().getReader();
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      chunks.push(value);
    }
    input = Buffer.concat(chunks).toString("utf-8");
  }

  const result = validateJson(input);
  const elapsed = (performance.now() - startTime).toFixed(2);

  if (result.valid) {
    console.log(`Valid JSON (${elapsed}ms)`);
    process.exit(0);
  } else {
    console.error(`Invalid JSON: ${result.error} (byte offset: ${result.byteOffset})`);
    console.error(`Validation took ${elapsed}ms`);
    process.exit(1);
  }
}

import { describe, expect, test } from "bun:test";
import { validateJson } from "./validate-json";

describe("validateJson", () => {
  describe("valid JSON", () => {
    test("empty object", () => {
      expect(validateJson("{}")).toEqual({ valid: true });
    });

    test("empty array", () => {
      expect(validateJson("[]")).toEqual({ valid: true });
    });

    test("simple object with string value", () => {
      expect(validateJson('{"name":"Alice"}')).toEqual({ valid: true });
    });

    test("nested objects", () => {
      expect(validateJson('{"a":{"b":{"c":1}}}')).toEqual({ valid: true });
    });

    test("array of mixed types", () => {
      expect(validateJson('[1,"two",true,null,{},[]]')).toEqual({ valid: true });
    });

    test("number formats", () => {
      expect(validateJson("0")).toEqual({ valid: true });
      expect(validateJson("-1")).toEqual({ valid: true });
      expect(validateJson("3.14")).toEqual({ valid: true });
      expect(validateJson("1e10")).toEqual({ valid: true });
      expect(validateJson("1E10")).toEqual({ valid: true });
      expect(validateJson("-2.5e+3")).toEqual({ valid: true });
      expect(validateJson("1.0e-5")).toEqual({ valid: true });
    });

    test("string escape sequences", () => {
      expect(validateJson('"hello\\nworld"')).toEqual({ valid: true });
      expect(validateJson('"tab\\there"')).toEqual({ valid: true });
      expect(validateJson('"back\\\\slash"')).toEqual({ valid: true });
      expect(validateJson('"quote\\"mark"')).toEqual({ valid: true });
    });

    test("unicode escapes", () => {
      expect(validateJson('"\\u0041"')).toEqual({ valid: true });
      expect(validateJson('"\\u00e9"')).toEqual({ valid: true });
      expect(validateJson('"\\uD83D\\uDE00"')).toEqual({ valid: true });
    });

    test("whitespace around values", () => {
      expect(validateJson("  { }  ")).toEqual({ valid: true });
      expect(validateJson("\t[\n]\r\n")).toEqual({ valid: true });
      expect(validateJson(' { "a" : 1 , "b" : 2 } ')).toEqual({ valid: true });
    });

    test("deeply nested structures", () => {
      const depth = 100;
      const nested = "[".repeat(depth) + "]".repeat(depth);
      expect(validateJson(nested)).toEqual({ valid: true });
    });

    test("large payload", () => {
      const entries = Array.from({ length: 1000 }, (_, i) => `"key${i}":${i}`);
      const payload = `{${entries.join(",")}}`;
      expect(validateJson(payload)).toEqual({ valid: true });
    });

    test("boolean and null literals", () => {
      expect(validateJson("true")).toEqual({ valid: true });
      expect(validateJson("false")).toEqual({ valid: true });
      expect(validateJson("null")).toEqual({ valid: true });
    });
  });

  describe("invalid JSON", () => {
    test("trailing comma in object", () => {
      const result = validateJson('{"a":1,}');
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
    });

    test("trailing comma in array", () => {
      const result = validateJson("[1,2,]");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
    });

    test("unquoted keys", () => {
      const result = validateJson("{a:1}");
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Expected string key");
    });

    test("single quotes", () => {
      const result = validateJson("{'a':1}");
      expect(result.valid).toBe(false);
    });

    test("truncated input - incomplete object", () => {
      const result = validateJson('{"a":');
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
    });

    test("truncated input - incomplete array", () => {
      const result = validateJson("[1,2,");
      expect(result.valid).toBe(false);
    });

    test("truncated input - incomplete string", () => {
      const result = validateJson('"hello');
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Unterminated string");
    });

    test("empty input", () => {
      const result = validateJson("");
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Empty input");
    });

    test("whitespace-only input", () => {
      const result = validateJson("   ");
      expect(result.valid).toBe(false);
    });

    test("extra content after value", () => {
      const result = validateJson("{}[]");
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Unexpected content after JSON value");
    });

    test("invalid escape sequence", () => {
      const result = validateJson('"\\x41"');
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Invalid escape character");
    });

    test("invalid unicode escape", () => {
      const result = validateJson('"\\uGGGG"');
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Invalid unicode escape");
    });

    test("bare word", () => {
      const result = validateJson("undefined");
      expect(result.valid).toBe(false);
    });

    test("leading zeros in number", () => {
      const result = validateJson("01");
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Unexpected content after JSON value");
    });

    test("missing colon in object", () => {
      const result = validateJson('{"a" 1}');
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Expected ':'");
    });

    test("control character in string", () => {
      const result = validateJson('"hello\x01world"');
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Invalid control character");
    });
  });

  describe("error reporting", () => {
    test("provides byte offset on error", () => {
      const result = validateJson('{"valid": tru}');
      expect(result.valid).toBe(false);
      expect(result.byteOffset).toBeDefined();
      expect(typeof result.byteOffset).toBe("number");
    });

    test("byte offset points to error location", () => {
      const result = validateJson("   !");
      expect(result.valid).toBe(false);
      expect(result.byteOffset).toBe(3);
    });
  });
});

/**
 * High-performance JSON validation using a single-pass character scanner.
 * Validates structural correctness without building a parsed object.
 */

export interface ValidationResult {
  valid: boolean;
  error?: string;
  byteOffset?: number;
}

const WHITESPACE = new Set([0x20, 0x09, 0x0a, 0x0d]); // space, tab, newline, carriage return

/**
 * Validate JSON string using a single-pass character scanner.
 * Avoids full parse overhead by scanning character-by-character
 * and tracking structural validity without object allocation.
 */
export function validateJson(input: string): ValidationResult {
  const len = input.length;
  let pos = 0;

  function error(msg: string): ValidationResult {
    return { valid: false, error: msg, byteOffset: pos };
  }

  function skipWhitespace(): void {
    while (pos < len && WHITESPACE.has(input.charCodeAt(pos))) {
      pos++;
    }
  }

  function parseValue(): ValidationResult | null {
    skipWhitespace();
    if (pos >= len) return error("Unexpected end of input");

    const ch = input.charCodeAt(pos);

    if (ch === 0x22) return parseString(); // "
    if (ch === 0x7b) return parseObject(); // {
    if (ch === 0x5b) return parseArray(); // [
    if (ch === 0x74) return parseLiteral("true"); // t
    if (ch === 0x66) return parseLiteral("false"); // f
    if (ch === 0x6e) return parseLiteral("null"); // n
    if (ch === 0x2d || (ch >= 0x30 && ch <= 0x39)) return parseNumber(); // - or 0-9

    return error(`Unexpected character '${input[pos]}' at position ${pos}`);
  }

  function parseString(): ValidationResult | null {
    pos++; // skip opening "
    while (pos < len) {
      const ch = input.charCodeAt(pos);
      if (ch === 0x22) { // closing "
        pos++;
        return null;
      }
      if (ch === 0x5c) { // backslash
        pos++;
        if (pos >= len) return error("Unexpected end of input in string escape");
        const esc = input.charCodeAt(pos);
        if (
          esc === 0x22 || esc === 0x5c || esc === 0x2f || // " \ /
          esc === 0x62 || esc === 0x66 || esc === 0x6e || // b f n
          esc === 0x72 || esc === 0x74 // r t
        ) {
          pos++;
        } else if (esc === 0x75) { // u
          pos++;
          for (let i = 0; i < 4; i++) {
            if (pos >= len) return error("Unexpected end of input in unicode escape");
            const hex = input.charCodeAt(pos);
            if (
              !((hex >= 0x30 && hex <= 0x39) || // 0-9
                (hex >= 0x41 && hex <= 0x46) || // A-F
                (hex >= 0x61 && hex <= 0x66))   // a-f
            ) {
              return error(`Invalid unicode escape character '${input[pos]}' at position ${pos}`);
            }
            pos++;
          }
        } else {
          return error(`Invalid escape character '${input[pos]}' at position ${pos}`);
        }
      } else if (ch < 0x20) {
        return error(`Invalid control character at position ${pos}`);
      } else {
        pos++;
      }
    }
    return error("Unterminated string");
  }

  function parseNumber(): ValidationResult | null {
    if (input.charCodeAt(pos) === 0x2d) pos++; // optional -

    if (pos >= len) return error("Unexpected end of input in number");

    if (input.charCodeAt(pos) === 0x30) { // leading 0
      pos++;
    } else if (input.charCodeAt(pos) >= 0x31 && input.charCodeAt(pos) <= 0x39) {
      pos++;
      while (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {
        pos++;
      }
    } else {
      return error(`Invalid number character '${input[pos]}' at position ${pos}`);
    }

    // fractional part
    if (pos < len && input.charCodeAt(pos) === 0x2e) { // .
      pos++;
      if (pos >= len || input.charCodeAt(pos) < 0x30 || input.charCodeAt(pos) > 0x39) {
        return error(`Expected digit after decimal point at position ${pos}`);
      }
      while (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {
        pos++;
      }
    }

    // exponent part
    if (pos < len && (input.charCodeAt(pos) === 0x65 || input.charCodeAt(pos) === 0x45)) { // e or E
      pos++;
      if (pos < len && (input.charCodeAt(pos) === 0x2b || input.charCodeAt(pos) === 0x2d)) { // + or -
        pos++;
      }
      if (pos >= len || input.charCodeAt(pos) < 0x30 || input.charCodeAt(pos) > 0x39) {
        return error(`Expected digit in exponent at position ${pos}`);
      }
      while (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {
        pos++;
      }
    }

    return null;
  }

  function parseLiteral(expected: string): ValidationResult | null {
    for (let i = 0; i < expected.length; i++) {
      if (pos >= len || input[pos] !== expected[i]) {
        return error(`Expected '${expected}' at position ${pos - i}`);
      }
      pos++;
    }
    return null;
  }

  function parseObject(): ValidationResult | null {
    pos++; // skip {
    skipWhitespace();

    if (pos < len && input.charCodeAt(pos) === 0x7d) { // empty object
      pos++;
      return null;
    }

    while (true) {
      skipWhitespace();
      if (pos >= len) return error("Unexpected end of input in object");

      if (input.charCodeAt(pos) !== 0x22) {
        return error(`Expected string key in object at position ${pos}`);
      }

      const keyErr = parseString();
      if (keyErr) return keyErr;

      skipWhitespace();
      if (pos >= len || input.charCodeAt(pos) !== 0x3a) { // :
        return error(`Expected ':' after object key at position ${pos}`);
      }
      pos++;

      const valErr = parseValue();
      if (valErr) return valErr;

      skipWhitespace();
      if (pos >= len) return error("Unexpected end of input in object");

      if (input.charCodeAt(pos) === 0x7d) { // }
        pos++;
        return null;
      }

      if (input.charCodeAt(pos) !== 0x2c) { // ,
        return error(`Expected ',' or '}' in object at position ${pos}`);
      }
      pos++;
    }
  }

  function parseArray(): ValidationResult | null {
    pos++; // skip [
    skipWhitespace();

    if (pos < len && input.charCodeAt(pos) === 0x5d) { // empty array
      pos++;
      return null;
    }

    while (true) {
      const valErr = parseValue();
      if (valErr) return valErr;

      skipWhitespace();
      if (pos >= len) return error("Unexpected end of input in array");

      if (input.charCodeAt(pos) === 0x5d) { // ]
        pos++;
        return null;
      }

      if (input.charCodeAt(pos) !== 0x2c) { // ,
        return error(`Expected ',' or ']' in array at position ${pos}`);
      }
      pos++;
    }
  }

  // Main validation logic
  skipWhitespace();
  if (pos >= len) return error("Empty input");

  const result = parseValue();
  if (result) return result;

  skipWhitespace();
  if (pos < len) {
    return error(`Unexpected content after JSON value at position ${pos}`);
  }

  return { valid: true };
}

// CLI entry point: runs when executed directly via `bun run src/validate-json.ts`
if (import.meta.main) {
  const startTime = performance.now();
  const filePath = process.argv[2];

  let input: string;

  if (filePath) {
    try {
      input = await Bun.file(filePath).text();
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      console.error(`Error reading file: ${message}`);
      process.exit(1);
    }
  } else {
    const chunks: Uint8Array[] = [];
    const reader = Bun.stdin.stream().getReader();
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      chunks.push(value);
    }
    input = Buffer.concat(chunks).toString("utf-8");
  }

  const result = validateJson(input);
  const elapsed = (performance.now() - startTime).toFixed(2);

  if (result.valid) {
    console.log(`Valid JSON (${elapsed}ms)`);
    process.exit(0);
  } else {
    console.error(`Invalid JSON: ${result.error} (byte offset: ${result.byteOffset})`);
    console.error(`Validation took ${elapsed}ms`);
    process.exit(1);
  }
}

import { describe, expect, test } from "bun:test";
import { validateJson } from "./validate-json";

describe("validateJson", () => {
  describe("valid JSON", () => {
    test("empty object", () => {
      expect(validateJson("{}")).toEqual({ valid: true });
    });

    test("empty array", () => {
      expect(validateJson("[]")).toEqual({ valid: true });
    });

    test("simple object with string value", () => {
      expect(validateJson('{"name":"Alice"}')).toEqual({ valid: true });
    });

    test("nested objects", () => {
      expect(validateJson('{"a":{"b":{"c":1}}}')).toEqual({ valid: true });
    });

    test("array of mixed types", () => {
      expect(validateJson('[1,"two",true,null,{},[]]')).toEqual({ valid: true });
    });

    test("number formats", () => {
      expect(validateJson("0")).toEqual({ valid: true });
      expect(validateJson("-1")).toEqual({ valid: true });
      expect(validateJson("3.14")).toEqual({ valid: true });
      expect(validateJson("1e10")).toEqual({ valid: true });
      expect(validateJson("1E10")).toEqual({ valid: true });
      expect(validateJson("-2.5e+3")).toEqual({ valid: true });
      expect(validateJson("1.0e-5")).toEqual({ valid: true });
    });

    test("string escape sequences", () => {
      expect(validateJson('"hello\\nworld"')).toEqual({ valid: true });
      expect(validateJson('"tab\\there"')).toEqual({ valid: true });
      expect(validateJson('"back\\\\slash"')).toEqual({ valid: true });
      expect(validateJson('"quote\\"mark"')).toEqual({ valid: true });
    });

    test("unicode escapes", () => {
      expect(validateJson('"\\u0041"')).toEqual({ valid: true });
      expect(validateJson('"\\u00e9"')).toEqual({ valid: true });
      expect(validateJson('"\\uD83D\\uDE00"')).toEqual({ valid: true });
    });

    test("whitespace around values", () => {
      expect(validateJson("  { }  ")).toEqual({ valid: true });
      expect(validateJson("\t[\n]\r\n")).toEqual({ valid: true });
      expect(validateJson(' { "a" : 1 , "b" : 2 } ')).toEqual({ valid: true });
    });

    test("deeply nested structures", () => {
      const depth = 100;
      const nested = "[".repeat(depth) + "]".repeat(depth);
      expect(validateJson(nested)).toEqual({ valid: true });
    });

    test("large payload", () => {
      const entries = Array.from({ length: 1000 }, (_, i) => `"key${i}":${i}`);
      const payload = `{${entries.join(",")}}`;
      expect(validateJson(payload)).toEqual({ valid: true });
    });

    test("boolean and null literals", () => {
      expect(validateJson("true")).toEqual({ valid: true });
      expect(validateJson("false")).toEqual({ valid: true });
      expect(validateJson("null")).toEqual({ valid: true });
    });
  });

  describe("invalid JSON", () => {
    test("trailing comma in object", () => {
      const result = validateJson('{"a":1,}');
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
    });

    test("trailing comma in array", () => {
      const result = validateJson("[1,2,]");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
    });

    test("unquoted keys", () => {
      const result = validateJson("{a:1}");
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Expected string key");
    });

    test("single quotes", () => {
      const result = validateJson("{'a':1}");
      expect(result.valid).toBe(false);
    });

    test("truncated input - incomplete object", () => {
      const result = validateJson('{"a":');
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
    });

    test("truncated input - incomplete array", () => {
      const result = validateJson("[1,2,");
      expect(result.valid).toBe(false);
    });

    test("truncated input - incomplete string", () => {
      const result = validateJson('"hello');
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Unterminated string");
    });

    test("empty input", () => {
      const result = validateJson("");
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Empty input");
    });

    test("whitespace-only input", () => {
      const result = validateJson("   ");
      expect(result.valid).toBe(false);
    });

    test("extra content after value", () => {
      const result = validateJson("{}[]");
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Unexpected content after JSON value");
    });

    test("invalid escape sequence", () => {
      const result = validateJson('"\\x41"');
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Invalid escape character");
    });

    test("invalid unicode escape", () => {
      const result = validateJson('"\\uGGGG"');
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Invalid unicode escape");
    });

    test("bare word", () => {
      const result = validateJson("undefined");
      expect(result.valid).toBe(false);
    });

    test("leading zeros in number", () => {
      const result = validateJson("01");
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Unexpected content after JSON value");
    });

    test("missing colon in object", () => {
      const result = validateJson('{"a" 1}');
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Expected ':'");
    });

    test("control character in string", () => {
      const result = validateJson('"hello\x01world"');
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Invalid control character");
    });
  });

  describe("error reporting", () => {
    test("provides byte offset on error", () => {
      const result = validateJson('{"valid": tru}');
      expect(result.valid).toBe(false);
      expect(result.byteOffset).toBeDefined();
      expect(typeof result.byteOffset).toBe("number");
    });

    test("byte offset points to error location", () => {
      const result = validateJson("   !");
      expect(result.valid).toBe(false);
      expect(result.byteOffset).toBe(3);
    });
  });
});
